// Generated by scripts/build-workflows.mjs. Edit n8n/code/, not here.
// ---- ../stable-ids.js ----
// Gives every node of a semantic DOM tree a stable id (e_N) that survives
// across snapshots of the same tab, so changes can be expressed as
// add / remove / update operations on element ids.
//
// A node's signature is its parent's id + tag + its strongest identity
// (id, test id, name, aria-label, href, label or a hash of its text), plus an
// occurrence index among same-signature siblings. Signatures seen in the
// previous snapshot map back to the same id.

const GENERATED_ID = /\d{4,}|^:r|^[a-f0-9-]{12,}$/i;

function strHash(str) {
    let h = 0x811c9dc5;
    for (let i = 0; i < str.length; i++) {
        h ^= str.charCodeAt(i);
        h = Math.imul(h, 0x01000193);
    }
    return (h >>> 0).toString(36);
}

function nodeIdentity(node, depth = 0) {
    const a = node.attrs || {};

    if (a.id && !GENERATED_ID.test(a.id)) return "#" + a.id;
    if (a["data-testid"]) return "t:" + a["data-testid"];
    if (a.name) return "n:" + a.name;
    if (a["aria-label"]) return "l:" + a["aria-label"];
    if (a.href) return "h:" + a.href;
    if (a.label) return "L:" + a.label;
    if (node.text) return "x:" + strHash(node.text);

    // Containers without identity take it from their first child, which stays
    // the same when content is appended (chats, feeds, lists).
    if (node.children && node.children.length && depth < 3) {
        const first = nodeIdentity(node.children[0], depth + 1);
        if (first) return "c:" + first;
    }

    return "";
}

function copyFields(from, to) {
    for (const key of ["text", "attrs", "value", "checked", "selected"]) {
        if (from[key] !== undefined) {
            to[key] = from[key];
        }
    }
    return to;
}

function assignIds(tree, idMap, nextId) {
    const oldMap = idMap || {};
    const newMap = {};
    let counter = nextId || 1;

    function idFor(signature) {
        const id = oldMap[signature] || "e_" + counter++;
        newMap[signature] = id;
        return id;
    }

    function visitChildren(children, parentId) {
        const seen = {};

        return children.map(child => {
            const base = `${parentId}>${child.tag}:${nodeIdentity(child)}`;
            const n = (seen[base] = (seen[base] || 0) + 1);
            const id = idFor(n > 1 ? `${base}#${n}` : base);

            const out = copyFields(child, { id, parentId, tag: child.tag });
            if (child.children && child.children.length) {
                out.children = visitChildren(child.children, id);
            }
            return out;
        });
    }

    const rootId = idFor("root:" + tree.tag);
    const root = copyFields(tree, { id: rootId, parentId: null, tag: tree.tag });
    if (tree.children && tree.children.length) {
        root.children = visitChildren(tree.children, rootId);
    }

    return { tree: root, idMap: newMap, nextId: counter };
}

// ---- ../diff.js ----
// Compares two id-annotated trees (see stable-ids.js) and returns operations:
//   { op: "add",    parentId, element }
//   { op: "remove", elementId }
//   { op: "update", elementId, changes }
// Only top-most added/removed elements are reported. Text changes that only
// differ in numbers or relative times ("5 min ago") are treated as noise.

const MEANINGFUL_ATTRS = ["href", "aria-expanded", "aria-selected", "disabled", "open", "label", "placeholder", "role"];

const RELATIVE_TIME = /\b(just now|now|today|yesterday|\d+\s*(s|secs?|seconds?|m|mins?|minutes?|h|hrs?|hours?|d|days?|w|weeks?|mo|months?|y|years?)\s*ago)\b/gi;

function normalizeNoise(text) {
    return String(text || "").replace(RELATIVE_TIME, "~").replace(/\d+/g, "0");
}

function indexTree(tree) {
    const index = new Map();

    (function walk(node) {
        index.set(node.id, node);
        for (const child of node.children || []) {
            walk(child);
        }
    })(tree);

    return index;
}

function withoutParentIds(node) {
    const out = { ...node };
    delete out.parentId;
    if (node.children) {
        out.children = node.children.map(withoutParentIds);
    }
    return out;
}

function diffTrees(prev, cur) {
    if (!prev) {
        return [];
    }

    const before = indexTree(prev);
    const after = indexTree(cur);
    const ops = [];

    for (const [id, node] of after) {
        const old = before.get(id);

        if (!old) {
            if (!node.parentId || before.has(node.parentId)) {
                ops.push({ op: "add", parentId: node.parentId, element: withoutParentIds(node) });
            }
            continue;
        }

        const changes = {};

        if ((old.text || "") !== (node.text || "") && normalizeNoise(old.text) !== normalizeNoise(node.text)) {
            changes.text = node.text || "";
        }
        if (old.value !== node.value) {
            changes.value = node.value === undefined ? null : node.value;
        }
        if (!!old.checked !== !!node.checked) {
            changes.checked = !!node.checked;
        }
        if (old.selected !== node.selected) {
            changes.selected = node.selected === undefined ? null : node.selected;
        }

        const oldAttrs = old.attrs || {};
        const newAttrs = node.attrs || {};
        for (const attr of MEANINGFUL_ATTRS) {
            if (oldAttrs[attr] !== newAttrs[attr]) {
                changes.attrs = changes.attrs || {};
                changes.attrs[attr] = newAttrs[attr] === undefined ? null : newAttrs[attr];
            }
        }

        if (Object.keys(changes).length) {
            ops.push({ op: "update", elementId: id, changes });
        }
    }

    for (const [id, node] of before) {
        if (!after.has(id) && (!node.parentId || after.has(node.parentId))) {
            ops.push({ op: "remove", elementId: id });
        }
    }

    return ops;
}

// ---- ../events.js ----
// Turns DOM diff operations and user interactions into short plain-English
// activity events, e.g.
//   Entered "personal-assistant" into "Repository name"
//   Clicked button "Create repository"
//   Message appeared: "Repository created successfully"

const MESSAGE_ROLES = new Set(["alert", "status", "alertdialog", "dialog"]);
const MAX_CONTENT_ITEMS = 5;
const MAX_CONTENT_CHARS = 600;

function clip(value, max) {
    const s = String(value == null ? "" : value).replace(/\s+/g, " ").trim();
    return s.length > max ? s.slice(0, max - 1) + "…" : s;
}

function hostPath(url) {
    try {
        const u = new URL(url);
        return u.host + u.pathname;
    } catch {
        return String(url);
    }
}

function textOf(node, max) {
    const parts = [];

    (function walk(n) {
        if (n.text) parts.push(n.text);
        for (const child of n.children || []) walk(child);
    })(node);

    return clip(parts.join(" "), max);
}

// Name of an interaction target ({ tag, type, role, label, text, name, ... }).
function targetName(t) {
    return t.label || t.text || t.ariaLabel || t.name || t.placeholder || "";
}

// Name of a tree node ({ tag, text, attrs }).
function nodeName(node) {
    const a = node.attrs || {};
    return a.label || a["aria-label"] || node.text || a.name || a.placeholder || "";
}

function targetKind(t) {
    if (t.role) return t.role;
    if (t.tag === "a") return "link";
    if (t.tag === "input" && /^(submit|button|reset)$/.test(t.type || "")) return "button";
    return t.tag || "element";
}

function isMessageNode(node) {
    const role = node.attrs && node.attrs.role;
    return node.tag === "dialog" || MESSAGE_ROLES.has(role);
}

function findMessage(node, depth = 0) {
    if (isMessageNode(node)) return node;
    if (depth > 4) return null;
    for (const child of node.children || []) {
        const found = findMessage(child, depth + 1);
        if (found) return found;
    }
    return null;
}

function toIso(at) {
    const d = new Date(at);
    return isNaN(d) ? new Date().toISOString() : d.toISOString();
}

// ctx: { at, url, prevUrl, title, isFirst }
// after: Map of id -> node for the current tree (indexTree in diff.js)
function toEvents(ops, interactions, ctx, after) {
    const events = [];
    const at = toIso(ctx.at);

    function push(time, kind, text) {
        if (!text) return;
        const last = events[events.length - 1];
        if (last && last.text === text) return;
        events.push({ at: time, kind, text });
    }

    if (ctx.isFirst || ctx.url !== ctx.prevUrl) {
        const title = clip(ctx.title || hostPath(ctx.url), 120);
        push(at, "navigation", `Opened "${title}" (${clip(hostPath(ctx.url), 150)})`);
    }

    // What the user did, in order.
    const handled = new Set();
    const sorted = [...(interactions || [])].sort((a, b) => (a.at || 0) - (b.at || 0));

    for (const it of sorted) {
        const t = it.target || {};
        const time = toIso(it.at || ctx.at);
        const name = clip(targetName(t), 80);

        if (it.kind === "click") {
            if (t.tag === "input" && (t.type === "checkbox" || t.type === "radio")) continue;
            if (name) push(time, "interaction", `Clicked ${targetKind(t)} "${name}"`);
        } else if (it.kind === "change") {
            if (!name) continue;
            handled.add(name);

            if (t.type === "checkbox") {
                push(time, "input", `${t.checked ? "Checked" : "Unchecked"} "${name}"`);
            } else if (t.type === "radio") {
                if (t.checked !== false) push(time, "input", `Selected "${name}"`);
            } else if (t.tag === "select") {
                push(time, "input", `Selected "${clip(t.value, 80)}" in "${name}"`);
            } else if (t.value === undefined) {
                push(time, "input", `Filled in "${name}"`);
            } else if (t.value === "") {
                push(time, "input", `Cleared "${name}"`);
            } else {
                push(time, "input", `Entered "${clip(t.value, 200)}" into "${name}"`);
            }
        } else if (it.kind === "submit") {
            push(time, "interaction", name ? `Submitted form "${name}"` : "Submitted a form");
        }
    }

    // What changed on the page.
    let contentItems = 0;
    let contentChars = 0;

    for (const op of ops) {
        if (op.op === "update") {
            const node = after.get(op.elementId);
            if (!node) continue;
            const name = clip(nodeName(node), 80);
            const changes = op.changes;

            if ("value" in changes && name && !handled.has(name) && changes.value) {
                push(at, "input", `Entered "${clip(changes.value, 200)}" into "${name}"`);
            }
            if ("checked" in changes && name && !handled.has(name)) {
                const isRadio = node.attrs && node.attrs.type === "radio";
                if (isRadio) {
                    // The other radio in the group unchecking is implied.
                    if (changes.checked) push(at, "input", `Selected "${name}"`);
                } else {
                    push(at, "input", `${changes.checked ? "Checked" : "Unchecked"} "${name}"`);
                }
            }
            if ("text" in changes && changes.text && isMessageNode(node)) {
                push(at, "message", `Message appeared: "${clip(changes.text, 200)}"`);
            }
        } else if (op.op === "add") {
            const el = op.element;

            const message = findMessage(el);
            if (message) {
                const text = textOf(message, 300);
                if (text) push(at, "message", `Message appeared: "${text}"`);
                continue;
            }

            if (/^h[1-6]$/.test(el.tag) && el.text) {
                push(at, "section", `Section appeared: "${clip(el.text, 150)}"`);
                continue;
            }

            if (contentItems >= MAX_CONTENT_ITEMS || contentChars >= MAX_CONTENT_CHARS) continue;
            const text = textOf(el, MAX_CONTENT_CHARS - contentChars);
            if (text.length >= 3) {
                contentItems++;
                contentChars += text.length;
                push(at, "content", `New content: "${text}"`);
            }
        }
    }

    return events;
}

// ---- ../ingest.js ----
// Processes one DOM snapshot from the extension against the tab's previous
// state: assign stable ids, diff, and derive activity events.
// Requires stable-ids.js, diff.js and events.js.
//
// body: { tabId, url, title, capturedAt, tree, interactions }
// prev: row from tmp_tab_state ({ url, tree, id_map, next_id }) or {}

function processSnapshot(body, prev) {
    const prevState = prev && prev.tree ? prev : null;
    const at = new Date(body.capturedAt || Date.now()).toISOString();

    const assigned = assignIds(body.tree, prevState && prevState.id_map, prevState && prevState.next_id);
    const ops = diffTrees(prevState ? prevState.tree : null, assigned.tree);

    const events = toEvents(
        ops,
        body.interactions || [],
        {
            at,
            url: body.url,
            prevUrl: prevState ? prevState.url : null,
            title: body.title,
            isFirst: !prevState
        },
        indexTree(assigned.tree)
    );

    let website = "unknown";
    try {
        website = new URL(body.url).hostname || "unknown";
    } catch {}

    return {
        tabId: String(body.tabId),
        url: body.url,
        title: body.title || "",
        website,
        tree: assigned.tree,
        idMap: assigned.idMap,
        nextId: assigned.nextId,
        ops,
        events
    };
}


// Input: the tab's previous state from "Load Tab State" (empty item if none).
const body = $('DOM Snapshot Webhook').first().json.body || {};

if (!body.url || !body.tree || body.tabId == null) {
    return [];
}

const result = processSnapshot(body, $input.first().json || {});

return [{
    json: {
        tabId: result.tabId,
        url: result.url,
        title: result.title,
        website: result.website,
        tree: JSON.stringify(result.tree),
        idMap: JSON.stringify(result.idMap),
        nextId: result.nextId,
        events: JSON.stringify(result.events),
        eventCount: result.events.length
    }
}];
